/**
 * Panda emits theme rules in @layer base, but @layer tokens resets --colors-aeon-*.
 * This file is unlayered and imported after styles.css so light/dark actually apply.
 */
import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { buildThemeGlobalCss } from '../src/theme/global-theme-css.js'

const __dirname = dirname(fileURLToPath(import.meta.url))
const outPath = join(__dirname, '../theme-runtime.css')

function declToCss(prop: string, value: string): string {
  if (prop === 'colorScheme') return `  color-scheme: ${value};`
  return `  ${prop}: ${value};`
}

function rulesToCss(rules: Record<string, Record<string, string | undefined>>): string {
  const lines = [
    '/* Generated by scripts/emit-theme-runtime.ts — do not edit */',
    '/* Import after @aeon-ui/panda/styles.css */',
    '',
  ]
  for (const [selector, decls] of Object.entries(rules)) {
    lines.push(`${selector} {`)
    for (const [prop, value] of Object.entries(decls)) {
      if (value !== undefined) lines.push(declToCss(prop, value))
    }
    lines.push('}', '')
  }
  return lines.join('\n')
}

const rules = buildThemeGlobalCss()

writeFileSync(outPath, rulesToCss(rules), 'utf8')
console.log(`Wrote ${outPath}`)
